const {categories,products}=CATALOG;
const page=document.body.dataset.page;
const wa='https://wa.me/9647722282272?text=';
const names={new:'جديد',used:'مستعمل'};
const availableConditions=p=>{
 if(p.condition==='new'||p.condition==='used')return [p.condition];
 // Older products may still have prices for both conditions.
 const found=['new','used'].filter(c=>Array.isArray(p.prices?.[c])&&p.prices[c].some(n=>Number(n)>0));
 return found.length?found:['new'];
};
const cleanlinessText=(p,c)=>c==='used'&&Number.isInteger(p.cleanliness)&&p.cleanliness>=1&&p.cleanliness<=100?'نظافة الجهاز: '+p.cleanliness+'%':'';
const money=n=>n.toLocaleString('en-US');
const price=(p,c)=>p.prices[c][0]===p.prices[c][1]?`${money(p.prices[c][0])} د.ع`:`من ${money(p.prices[c][0])} إلى ${money(p.prices[c][1])} د.ع`;
const link=(p,c)=>`/products/${p.id}/?condition=${c}`;
const ask=(p,c)=>wa+encodeURIComponent(`مرحبا معرض دبي، أستفسر عن ${p.name} — ${p.variant} (${names[c]})${cleanlinessText(p,c)?'، '+cleanlinessText(p,c):''}. أحتاج السعر النهائي وصور القطعة وحالتها والملحقات، وهل متوفر؟`);
function card(p,c){return `<article class="product"><a class="product-art photo-art" href="${link(p,c)}" aria-label="تفاصيل ${p.name} ${names[c]}"><span class="condition-tag ${c}">${names[c]}</span><img src="/assets/${p.image}" alt="صورة موديل ${p.name}" loading="lazy"><span class="photo-caption">صورة الموديل</span></a><div class="product-info"><span class="category">${p.brand} · ${p.variant}</span><h3><a href="${link(p,c)}">${p.name}</a></h3>${cleanlinessText(p,c)?'<div class="cleanliness-label">'+cleanlinessText(p,c)+'</div>':''}<p class="short-description">${p.description}</p><div class="price-label">سعر تقريبي · ${names[c]}</div><div class="price-range">${price(p,c)}</div><small class="availability">يُؤكّد التوفر من المعرض</small><a class="details-btn" href="${link(p,c)}">التفاصيل والمواصفات <span>←</span></a><a class="whatsapp-link" href="${ask(p,c)}" target="_blank" rel="noopener">استفسر على واتساب ↗</a></div></article>`}
function chips(values,selected){return values.map(v=>`<button data-sub="${v}" class="${v===selected?'selected':''}" aria-pressed="${v===selected}">${v==='all'?'الكل':v}</button>`).join('')}
const menus=[...document.querySelectorAll('.all-departments')];document.addEventListener('click',e=>{if(!e.target.closest('.all-departments'))menus.forEach(m=>m.open=false)});document.addEventListener('keydown',e=>{if(e.key==='Escape'){const m=menus.find(m=>m.open);if(m){m.open=false;m.querySelector('summary').focus()}}});document.querySelectorAll('.category-bar a').forEach(a=>{if(a.pathname===location.pathname){a.classList.add('selected');a.setAttribute('aria-current','page')}});
if(page==='home')document.querySelectorAll('[data-shelf]').forEach(shelf=>{
 const items=products.filter(p=>p.category===shelf.dataset.shelf);
 let selected='all',condition='all';
 const tabs=shelf.querySelector('.shelf-tabs');
 const strip=shelf.querySelector('.product-strip');
 const conditions=document.createElement('div');
 conditions.className='shelf-conditions';
 conditions.setAttribute('role','group');
 conditions.setAttribute('aria-label','حالة الأجهزة');
 tabs.after(conditions);
 strip.setAttribute('aria-label','منتجات '+categories.find(c=>c.id===shelf.dataset.shelf).title);
 strip.setAttribute('tabindex','0');
 function draw(){
  tabs.innerHTML=chips(['all',...new Set(items.map(p=>p.sub))],selected);
  conditions.innerHTML=['all','new','used'].map(c=>`<button data-shelf-condition="${c}" class="${condition===c?'selected':''}" aria-pressed="${condition===c}">${c==='all'?'الجديد والمستعمل':names[c]}</button>`).join('');
  strip.innerHTML=items.filter(p=>selected==='all'||p.sub===selected).flatMap(p=>availableConditions(p).filter(c=>condition==='all'||condition===c).map(c=>card(p,c))).join('');
  strip.scrollLeft=0;
 }
 shelf.addEventListener('click',e=>{
  const t=e.target.closest('[data-sub]');
  const c=e.target.closest('[data-shelf-condition]');
  if(t){selected=t.dataset.sub;draw();tabs.querySelector(`[data-sub="${selected}"]`).focus()}
  if(c){condition=c.dataset.shelfCondition;draw();conditions.querySelector(`[data-shelf-condition="${condition}"]`).focus()}
  const shift=e.target.closest('[data-shift]');
  if(shift)strip.scrollBy({left:-Number(shift.dataset.shift)*320,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
 });
 draw();
});
const category=categories.find(c=>c.id===page);
if(category){const items=products.filter(p=>p.category===page);const params=new URLSearchParams(location.search);const subs=['all',...new Set(items.map(p=>p.sub))];let sub=subs.includes(params.get('sub'))?params.get('sub'):'all';const condition=document.querySelector('#condition-filter'),brand=document.querySelector('#brand-filter'),search=document.querySelector('#catalog-search'),sort=document.querySelector('#sort-filter');condition.value=['new','used'].includes(params.get('condition'))?params.get('condition'):'all';brand.innerHTML='<option value="all">كل الماركات</option>'+[...new Set(items.map(p=>p.brand))].map(b=>`<option value="${b}">${b}</option>`).join('');brand.value=items.some(p=>p.brand===params.get('brand'))?params.get('brand'):'all';search.value=params.get('q')||'';sort.value=['low','high'].includes(params.get('sort'))?params.get('sort'):'default';
 function renderCategory(){const q=search.value.trim().toLowerCase();let entries=items.filter(p=>(sub==='all'||p.sub===sub)&&(brand.value==='all'||p.brand===brand.value)&&(p.name+' '+p.brand+' '+p.description+' '+p.variant).toLowerCase().includes(q)).flatMap(p=>availableConditions(p).filter(c=>condition.value==='all'||c===condition.value).map(c=>({p,c})));if(sort.value!=='default')entries.sort((a,b)=>(a.p.prices[a.c][0]-b.p.prices[b.c][0])*(sort.value==='low'?1:-1));document.querySelector('#category-products').innerHTML=entries.map(({p,c})=>card(p,c)).join('');document.querySelector('#sub-filters').innerHTML=chips(subs,sub);document.querySelector('#no-results').hidden=entries.length>0;document.querySelector('#result-count').textContent=entries.length+' خيارات للعرض';const u=new URL(location.href);for(const [k,v] of [['condition',condition.value],['brand',brand.value],['sub',sub],['q',search.value.trim()],['sort',sort.value]]){if(v==='all'||v==='default'||v==='')u.searchParams.delete(k);else u.searchParams.set(k,v)}history.replaceState(null,'',u)}
 document.querySelector('#sub-filters').addEventListener('click',e=>{const b=e.target.closest('[data-sub]');if(b){sub=b.dataset.sub;renderCategory()}});[condition,brand,sort].forEach(el=>el.addEventListener('change',renderCategory));search.addEventListener('input',renderCategory);document.querySelector('#reset-filters').addEventListener('click',()=>{sub='all';condition.value='all';brand.value='all';search.value='';sort.value='default';renderCategory()});renderCategory();}
if(page.startsWith('product:')){const p=products.find(p=>p.id===page.split(':')[1]);const cat=categories.find(c=>c.id===p.category);const offeredConditions=availableConditions(p);let condition=new URLSearchParams(location.search).get('condition');if(!offeredConditions.includes(condition))condition=offeredConditions[0];const checks={phones:'نسبة البطارية، حالة الشاشة والهيكل، وسجل الصيانة والقطع المستبدلة.',cameras:'حالة المستشعر والعدسة، عدد لقطات الشتر إن توفر، البطارية والملحقات.',gaming:'عمل المنافذ ووحدة التحكم، حالة التخزين، وأي صيانة سابقة. الألعاب والاشتراكات غير مشمولة إلا إذا أكد المعرض ذلك.',computers:'حالة الشاشة والمنافذ، صحة التخزين، والبطارية إن وجدت.',printing:'عينة طباعة وفحص رأس الطباعة أو الليزر حسب الطراز، وعدّاد الاستخدام إن توفر.',electronics:'سلامة التشغيل والبطارية إن وجدت، النظافة والملحقات والتوافق مع جهازك.'};
 function renderProduct(){document.querySelector('#product-page').innerHTML=`<div class="breadcrumbs"><a href="/">الرئيسية</a> / <a href="/${cat.id}/">${cat.title}</a> / ${p.name}</div><div class="product-detail-layout"><div class="detail-photo"><img src="/assets/${p.image}" alt="صورة ${p.name}"><small>صورة مرجعية للموديل؛ اطلب صور القطعة الفعلية من المعرض.</small></div><div class="detail-info"><span class="kicker">${p.brand} · ${p.sub}</span><h1>${p.name}</h1><p class="variant">${p.variant}</p><div class="condition-choices" role="group" aria-label="حالة الجهاز">${offeredConditions.length===1?`<span class="single-condition">${names[condition]}</span>`:offeredConditions.map(c=>`<button data-condition="${c}" class="${condition===c?'selected':''}" aria-pressed="${condition===c}">${names[c]}</button>`).join('')}</div><p>${p.description}</p>${cleanlinessText(p,condition)?`<div class="cleanliness-detail"><strong>${cleanlinessText(p,condition)}</strong><small>تقدير لحالة النظافة الخارجية، وليس لصحة البطارية أو نتيجة فحص فني.</small></div>`:''}<div class="detail-price"><span>نطاق سعر استرشادي · ${names[condition]}</span><div class="price-range">${price(p,condition)}</div><small>التوفر والسعر النهائي يُؤكّدان عبر واتساب.</small></div><a class="btn" href="${ask(p,condition)}" target="_blank" rel="noopener">اسأل عن السعر وصور القطعة ↗</a><a class="back-category" href="/${cat.id}/">رجوع إلى ${cat.title} ←</a></div></div><div class="product-detail-bottom"><section><h2>المواصفات والتفاصيل</h2><dl>${p.specs.map(([a,b])=>`<div><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl></section><section><h2>${condition==='used'?'قبل شراء المستعمل':'قبل إتمام الشراء'}</h2><p>${condition==='used'?checks[p.category]:'تأكد من النسخة، ختم العلبة، محتوياتها والضمان المتوفر قبل الشراء.'}</p><p>حالة كل قطعة تختلف، ووجود المنتج في الكتالوج لا يعني توفره في المخزون. لا توجد نسبة بطارية أو حالة فحص مؤكدة قبل الرجوع للمعرض.</p><details class="sources"><summary>مصادر وملاحظات الأسعار</summary><p>تقديرات تحريرية بتاريخ 17 أكتوبر 2026، بالاستئناس بالأسعار المعلنة في السوق. نطاق المستعمل تقديري حسب الحالة، وليس متوسطاً محسوباً أو عرض بيع من المعرض.</p><a target="_blank" rel="noopener" href="${p.source}">مرجع الموديل والمواصفات ↗</a><a target="_blank" rel="noopener" href="${p.market}">مرجع سوقي ↗</a><p>الصور من صفحات المنتجات لدى الشركات أو المتاجر المرجعية، وليست صور مخزون معرض دبي.</p></details></section></div><section class="related-products"><div class="shelf-heading"><h2>من نفس القسم</h2><a href="/${cat.id}/">عرض الكل ←</a></div><div class="products">${products.filter(x=>x.category===p.category&&x.id!==p.id).slice(0,4).map(x=>card(x,availableConditions(x).includes(condition)?condition:availableConditions(x)[0])).join('')}</div></section>`;const u=new URL(location.href);u.searchParams.set('condition',condition);history.replaceState(null,'',u)}document.querySelector('#product-page').addEventListener('click',e=>{const b=e.target.closest('[data-condition]');if(b){condition=b.dataset.condition;renderProduct();document.querySelector(`[data-condition="${condition}"]`).focus()}});renderProduct();}
const form=document.querySelector('#sell-form');if(form){document.querySelector('#kind').innerHTML=['موبايل','كاميرا','لابتوب أو حاسبة','جهاز ألعاب','طابعة','إلكترونيات أو مستلزمات'].map(v=>`<option>${v}</option>`).join('');form.addEventListener('submit',e=>{e.preventDefault();window.open(wa+encodeURIComponent(`مرحبا معرض دبي، عندي جهاز للبيع.\nالنوع: ${document.querySelector('#kind').value}\nالموديل: ${document.querySelector('#model').value.trim()}\nالحالة: ${document.querySelector('#condition').value.trim()}`),'_blank','noopener,noreferrer')})}
const motion=document.querySelector('#motion-toggle');let paused=matchMedia('(prefers-reduced-motion: reduce)').matches;try{paused=paused||localStorage.getItem('dubai-motion')==='off'}catch{}function setMotion(){document.body.classList.toggle('motion-paused',paused);motion.textContent=paused?'▷':'Ⅱ';motion.setAttribute('aria-pressed',String(paused));motion.setAttribute('aria-label',paused?'تشغيل حركة الخلفية':'إيقاف حركة الخلفية')}motion.addEventListener('click',()=>{paused=!paused;try{localStorage.setItem('dubai-motion',paused?'off':'on')}catch{}setMotion()});setMotion();
// Keep links shared from the earlier one-page version usable.
if(location.pathname==='/'&&location.hash){const [id,c,b]=location.hash.slice(1).split('/');if([...categories.map(c=>c.id),'sell','branches'].includes(id)){const url=new URL('/'+id+'/',location.origin);if(['new','used'].includes(c))url.searchParams.set('condition',c);if(b)url.searchParams.set('brand',b);location.replace(url.href)}}
